ee:variables.ee:set-variable:
%dw 2.0
output application/java
var document = trim(vars.documentNumber)
var pqr = trim(vars.pqrId)
---
(document ++ "/" ++ pqr ++ "/" ++ payload.fileName) replace " " with "_"

ee:message.ee:set-payload:
%dw 2.0
output application/json
var failedCount = sizeOf(vars.azureResults filter ($.status == "failed"))
---
{
	status: "201",
	message: "Files uploaded successfully",
	result: {
		state: if ( failedCount == 0 ) "success" 
          else if ( failedCount < sizeOf(vars.azureResults) ) "partial_success" 
          else "failed",
		tracingId: correlationId,
		summary: {
			totalFiles: sizeOf(vars.azureResults),
			processedFiles: sizeOf(vars.results filter ($.status == "uploaded")) default 0,
			failedFiles: failedCount
		},
		details: vars.azureResults
	}
}
